package akogen.fabric.v6;
import java.util.*;import java.util.function.Supplier;import java.io.*;
/** Keeps each wearer's custom textures on the original vanilla cape and elytra layers. */
public final class CapeBridge {
 static Map<Integer,Object> textures=new HashMap<Integer,Object>(),elytraTextures=new HashMap<Integer,Object>();static Class<?> avatarType;
 static final Set<Integer> drawLogged=new HashSet<Integer>();
 static final class SkinCopy{Object skin,id,copy;}
 static final Map<Integer,SkinCopy> skinCopies=new LinkedHashMap<Integer,SkinCopy>(64,.75f,true){protected boolean removeEldestEntry(Map.Entry<Integer,SkinCopy> e){return size()>64;}};
 static Object texture(Assets.Entry e,boolean wing)throws Exception{Map<Integer,Object> cache=wing?elytraTextures:textures;Object existing=cache.get(e.id);if(existing!=null)return existing;byte[] bytes=Assets.files.get("assets/akogen/"+(wing?"elytra/":"capes/")+e.id+".png");if(bytes==null)throw new IOException("Vanilla cape texture missing");Object image=Names.call(Names.type("com/mojang/blaze3d/platform/NativeImage"),"read",new ByteArrayInputStream(bytes));Object dynamic=Names.create("net/minecraft/client/renderer/texture/DynamicTexture",(Supplier<String>)()->"Akogen cape "+e.name,image);Object id=Names.call(Names.type("net/minecraft/resources/Identifier"),"fromNamespaceAndPath","akogen",(wing?"elytra/":"cape/")+e.id);Names.call(Names.call(Session.mc,"getTextureManager"),"register",id,dynamic);cache.put(e.id,id);return id;}
 public static void tick()throws Exception{if(avatarType==null){avatarType=Class.forName("net.minecraft.class_10055",true,Names.loader);Session.log("CAPE/ELYTRA READY: standard Fabric mixins, vanilla models and physics retained");}Assets.Entry e=Session.equipped.get("cloak");if(e!=null){texture(e,false);texture(e,true);}}
 public static void apply(Object avatar){if(!Session.active||avatarType==null||!avatarType.isInstance(avatar))return;try{int entityId=((Number)Names.field(avatar,"field_53528")).intValue();Assets.Entry entry=CosmeticSync.selectionForEntity(entityId).get("cloak");if(entry==null){SkinCopy previous=skinCopies.get(entityId);if(previous!=null&&Names.field(avatar,"field_53520")==previous.copy)Names.set(avatar,"field_53520",previous.skin);return;}Object skin=Names.field(avatar,"field_53520"),id=textures.get(entry.id);Object wingId=elytraTextures.get(entry.id);if(skin==null||id==null||wingId==null)return;SkinCopy cached=skinCopies.get(entityId);if(cached==null){cached=new SkinCopy();skinCopies.put(entityId,cached);}if(id!=cached.id||(skin!=cached.skin&&skin!=cached.copy)){Object cape=Names.create("net/minecraft/core/ClientAsset$DownloadedTexture",id,"akogen-local-cape");cached.copy=Names.create("net/minecraft/world/entity/player/PlayerSkin",Names.call(skin,"body"),cape,Names.create("net/minecraft/core/ClientAsset$DownloadedTexture",wingId,"akogen-local-elytra"),Names.call(skin,"model"),Names.call(skin,"secure"));cached.skin=skin;cached.id=id;}Names.set(avatar,"field_53520",cached.copy);if(drawLogged.add(entry.id))Session.log("CAPE DRAW OK: "+entry.name+"; vanilla cape and elytra meshes");}catch(Throwable t){Session.error(t);}}
}
